<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manajemen Pengguna — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;background:#f4f7fb}.layout{min-height:100vh;display:grid;grid-template-columns:275px 1fr}.side{background:linear-gradient(160deg,#23395d,#1d3152);color:#fff;padding:25px 14px;position:sticky;top:0;height:100vh;overflow:auto}.brand{display:flex;align-items:center;gap:10px;margin:0 10px 28px;font-size:23px;font-weight:800}.logo{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#ffffff18}.brand span{color:#a0b4d1}.section{margin:19px 11px 7px;color:#a0b4d1;font-size:10px;font-weight:800;letter-spacing:1px}.side a,.side button{display:flex;width:100%;gap:9px;align-items:center;padding:10px 11px;margin:3px 0;border:0;border-radius:9px;background:transparent;color:#dbe5f3;font:700 12px Inter;text-align:left;text-decoration:none;cursor:pointer}.side a:hover,.side a.active{background:#ffffff17;color:#fff}.side .child{padding-left:28px;color:#c2d1e3;font-size:11px}.side .logout{margin-top:19px;color:#fecaca}.main{max-width:1320px;width:100%;margin:auto;padding:35px 38px}.hero{position:relative;overflow:hidden;padding:28px 30px;border-radius:21px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.hero:after{content:"✦";position:absolute;right:26px;top:-45px;font-size:165px;color:#ffffff18}.hero>*{position:relative}.hero p{margin:0;color:#e7effa}.hero h1{margin:7px 0;font-size:28px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:18px 0}.mini,.card{background:#fffd;border:1px solid #fff;border-radius:17px;box-shadow:0 10px 23px #23395d0d}.mini{padding:17px}.mini span{color:#64748b;font-size:12px}.mini strong{display:block;font-size:27px;color:#23395d;margin-top:5px}.grid{display:grid;grid-template-columns:355px 1fr;gap:19px}.card{overflow:hidden}.head{padding:18px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0}.head h2{margin:0;color:#23395d;font-size:17px}.head p{margin:5px 0 0;color:#64748b;font-size:12px}.form{padding:18px 20px}.field{display:grid;gap:6px;margin:12px 0}.field label{font-size:11px;font-weight:800;color:#475569}input,select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:10px;font:14px Inter;outline:0}.btn{border:0;border-radius:9px;padding:9px 11px;background:#23395d;color:#fff;font:700 12px Inter;cursor:pointer}.save{width:100%;padding:12px}.red{background:#b91c1c}.success{margin:15px 0;padding:11px 13px;border-radius:10px;background:#dcfce7;color:#166534;font-size:13px}.error{color:#b91c1c;font-size:12px}.groups{display:grid;gap:17px}.group{padding:0 15px 14px}.group-title{display:flex;align-items:center;justify-content:space-between;padding:17px 5px 7px;color:#23395d}.group-title h3{margin:0;font-size:15px}.count{padding:5px 8px;border-radius:20px;background:#e8eef7;color:#365d92;font-size:11px;font-weight:800}.table{overflow:auto}table{width:100%;min-width:700px;border-collapse:separate;border-spacing:0 7px}th{padding:7px 10px;color:#64748b;text-align:left;font-size:10px;letter-spacing:.5px;text-transform:uppercase}td{padding:11px 10px;background:#f8fafc;border-top:1px solid #eef2f7;border-bottom:1px solid #eef2f7;font-size:13px}td:first-child{border-left:1px solid #eef2f7;border-radius:10px 0 0 10px}td:last-child{border-right:1px solid #eef2f7;border-radius:0 10px 10px 0}.avatar{display:inline-grid;place-items:center;width:30px;height:30px;margin-right:7px;border-radius:9px;background:#e8eef7;color:#23395d;font-size:12px;font-weight:800;vertical-align:middle}.status{padding:5px 8px;border-radius:20px;background:#e8eef7;color:#365d92;font-size:11px;font-weight:800}.inactive{background:#f1f5f9;color:#64748b}.actions{display:flex;gap:6px;align-items:center;white-space:nowrap}.edit{color:#365d92;text-decoration:none;font-size:12px;font-weight:800}.empty{color:#64748b;padding:14px 5px;font-size:13px}@media(max-width:940px){.layout{grid-template-columns:1fr}.side{position:static;height:auto;display:flex;flex-wrap:wrap;align-items:center}.brand{width:100%;margin-bottom:8px}.section{display:none}.side a,.side button{width:auto}.side .child{padding-left:11px}.side .logout{margin-top:3px}.main{padding:27px}.grid{grid-template-columns:1fr}}@media(max-width:600px){.main{padding:20px 14px}.summary{grid-template-columns:1fr}.hero{padding:24px}}</style></head><body><div class="layout"><aside class="side"><p class="brand"><i class="logo">🎓</i>FR<span>Exam</span></p><p class="section">UTAMA</p><a href="{{ route('admin.overview') }}">⌂ Pusat Kendali</a><a class="active" href="{{ route('admin.users') }}">♙ Manajemen Pengguna</a><p class="section">▣ DATA AKADEMIK</p><a class="child" href="{{ route('admin.workspace','classes') }}">├─ Kelas</a><a class="child" href="{{ route('admin.workspace','subjects') }}">├─ Mata Pelajaran</a><a class="child" href="{{ route('admin.workspace','academic-years') }}">└─ Tahun Ajaran</a><p class="section">📝 MANAJEMEN UJIAN</p><a class="child" href="{{ route('admin.workspace','exams') }}">├─ Daftar Ujian</a><a class="child" href="{{ route('admin.workspace','question-bank') }}">├─ Bank Soal</a><a class="child" href="{{ route('admin.workspace','schedules') }}">├─ Jadwal Ujian</a><a class="child" href="{{ route('admin.workspace','participants') }}">└─ Peserta Ujian</a><p class="section">◉ MONITORING UJIAN</p><a class="child" href="{{ route('admin.workspace','live-exams') }}">├─ Ujian Berlangsung</a><a class="child" href="{{ route('admin.workspace','participant-activity') }}">└─ Aktivitas Peserta</a><p class="section">📑 LAPORAN</p><a class="child" href="{{ route('admin.workspace','exam-report') }}">├─ Laporan Ujian</a><a class="child" href="{{ route('admin.workspace','scores') }}">├─ Laporan Nilai</a><a class="child" href="{{ route('admin.workspace','participant-recap') }}">└─ Rekap Peserta</a><form method="post" action="{{ route('logout') }}">@csrf<button class="logout">↪ Keluar</button></form></aside><main class="main"><section class="hero"><p>ADMIN WORKSPACE</p><h1>Manajemen Pengguna</h1><p>Data akun dipisahkan berdasarkan peran agar mudah dikelola dan dipantau.</p></section><section class="summary"><article class="mini"><span>Administrator</span><strong>{{ $admins->count() }}</strong></article><article class="mini"><span>Guru</span><strong>{{ $teachers->count() }}</strong></article><article class="mini"><span>Siswa</span><strong>{{ $students->count() }}</strong></article></section>@if(session('success'))<p class="success">✓ {{ session('success') }}</p>@endif<div class="grid"><section class="card"><header class="head"><h2>Tambah Akun</h2><p>Pilih peran lalu lengkapi data pengguna.</p></header><form class="form" method="post" action="{{ route('admin.users.store') }}">@csrf<div class="field"><label>NAMA LENGKAP</label><input name="name" value="{{ old('name') }}" required></div><div class="field"><label>PERAN PENGGUNA</label><select id="role" name="role"><option value="student">Siswa</option><option value="teacher">Guru</option><option value="admin">Admin</option></select></div><div class="field"><label id="identityLabel">NISN</label><input id="identity" name="nisn" value="{{ old('nisn') }}" required></div><div class="field" id="studentField"><label>KELAS SISWA</label><input name="class_name" value="{{ old('class_name') }}"></div><div id="teacherFields" style="display:none"><div class="field"><label>MAPEL YANG DIAMPU</label><input name="teaching_subject" value="{{ old('teaching_subject') }}"></div><div class="field"><label>KELAS YANG DIAMPU</label><input name="teaching_class" value="{{ old('teaching_class') }}"></div></div><div class="field"><label>PASSWORD</label><input type="password" name="password" required></div><div class="field"><label>KONFIRMASI PASSWORD</label><input type="password" name="password_confirmation" required></div><button class="btn save">+ Simpan Akun</button>@foreach($errors->all() as $error)<p class="error">{{ $error }}</p>@endforeach</form></section><section class="card"><header class="head"><h2>Daftar Pengguna Terpisah</h2><p>Admin, guru, dan siswa dikelompokkan dalam daftar masing-masing.</p></header><div class="groups">@foreach(['Administrator'=>$admins,'Guru'=>$teachers,'Siswa'=>$students] as $title=>$group)<section class="group"><header class="group-title"><h3>{{ $title }}</h3><span class="count">{{ $group->count() }} akun</span></header>@if($group->isEmpty())<p class="empty">Belum ada data {{ strtolower($title) }}.</p>@else<div class="table"><table><thead><tr><th>Nama</th><th>Identitas</th>@if($title==='Guru')<th>Mapel Diampu</th><th>Kelas Diampu</th>@elseif($title==='Siswa')<th>Kelas</th>@endif<th>Status</th><th>Aksi</th></tr></thead><tbody>@foreach($group as $user)<tr><td><i class="avatar">{{ strtoupper(mb_substr($user->name,0,1)) }}</i><strong>{{ $user->name }}</strong></td><td>{{ $user->role==='student'?$user->nisn:($user->role==='teacher'?$user->nip:$user->username) }}</td>@if($title==='Guru')<td>{{ $user->teaching_subject??'—' }}</td><td>{{ $user->teaching_class??'—' }}</td>@elseif($title==='Siswa')<td>{{ $user->class_name??'—' }}</td>@endif<td><span class="status {{ !$user->is_active?'inactive':'' }}">{{ $user->is_active?'Aktif':'Nonaktif' }}</span></td><td>@if($user->id!==auth()->id())<div class="actions"><a class="edit" href="{{ route('admin.users.edit',$user) }}">Ubah</a><form method="post" action="{{ route('admin.users.toggle',$user) }}">@csrf @method('PATCH')<button class="btn">{{ $user->is_active?'Nonaktif':'Aktifkan' }}</button></form><form method="post" action="{{ route('admin.users.destroy',$user) }}" onsubmit="return confirm('Hapus akun {{ $user->name }}?')">@csrf @method('DELETE')<button class="btn red">Hapus</button></form></div>@endif</td></tr>@endforeach</tbody></table></div>@endif</section>@endforeach</div></section></div></main></div><script>const role=document.querySelector('#role'),identity=document.querySelector('#identity'),label=document.querySelector('#identityLabel'),student=document.querySelector('#studentField'),teacher=document.querySelector('#teacherFields');function sync(){const r=role.value;identity.name=r==='student'?'nisn':r==='teacher'?'nip':'username';label.textContent=r==='student'?'NISN':r==='teacher'?'NIP':'USERNAME';student.style.display=r==='student'?'grid':'none';teacher.style.display=r==='teacher'?'block':'none'}role.addEventListener('change',sync);sync()</script></body></html>
